// 欠薪二十实付七，补款十只付十；同 tick 重试与读档不能再发工资。
void wage_and_checkpoint(){Fixture f;auto observation=observe_local_supply(f.common,f.economy,f.catalog);assert(observation.ok&&observation.value.size()==1&&!observation.value[0].source_fact_id.empty());auto first=f.step(1);assert(f.common.wallet("teacher.wallet")->balance==7&&outstanding_arrears(f.economy,"teacher.salary").value==13&&f.economy.arrears.size()==1);const auto ids=f.common.state().next_instance_id;const auto payments=f.economy.payments.size();OrganizationAccess read(f.common,f.organizations,f.org_catalog,f.economy);auto retry=step_local_economy(f.common,f.economy,f.catalog,read,f.activities,{0,1,{},{},{}});assert(retry.ok&&retry.value.fact_ids.empty()&&f.common.state().next_instance_id==ids&&f.economy.payments.size()==payments);assert(f.common.apply_resources({{WalletDelta{"city.wallet",10,true}},{}}).ok);f.step(2);assert(f.common.wallet("teacher.wallet")->balance==17&&outstanding_arrears(f.economy,"teacher.salary").value==3&&f.economy.arrears.size()==1);f.validate();
    CodecVisitor::Buffer bytes;CodecVisitor writer(bytes);auto copy=f.economy;auto org=f.organizations;assert(visit_local_economy_checkpoint(writer,copy).ok&&visit_organization_checkpoint(writer,org).ok&&writer.finish().ok);LocalEconomyState restored;OrganizationState restored_org;const auto& input=bytes;CodecVisitor reader(input);assert(visit_local_economy_checkpoint(reader,restored).ok&&visit_organization_checkpoint(reader,restored_org).ok&&reader.finish().ok);assert(compare_boundary(encode_local_economy_state(f.economy),encode_local_economy_state(restored)).exact());assert(compare_boundary(encode_organization_state(f.organizations),encode_organization_state(restored_org)).exact());auto cold=decode_local_economy_state(encode_local_economy_state(restored));assert(cold.ok);f.economy=std::move(cold.value);f.step(3);assert(f.common.wallet("teacher.wallet")->balance==17&&outstanding_arrears(f.economy,"teacher.salary").value==3);f.validate();auto damaged=f.economy;damaged.arrears.rows()[0].second.paid_amount=19;assert(!validate_local_economy(f.common,damaged,f.catalog,read).ok);
    auto invoice=local_economy_dynamic_fact(f.economy,f.economy.arrears.rows()[0].first);assert(invoice&&invoice->obligation&&invoice->obligation->paid_amount==0);auto payment=local_economy_dynamic_fact(f.economy,f.economy.payments.rows()[0].first);assert(payment->obligation->paid_amount==7);
}
