// 征募扣转真实劳力；供养持续，训练完成只成候补并释放训练位。
void population_training(){Fixture f;auto wallet=f.common.wallet("family.wallet")->balance;OrganizationRecruitCommand command;command.authority={"city","mayor.office",0,"mayor"};command.source_cohort_id="workers";command.target_cohort_id="trainees";command.activity_terms_id="voluntary.training";command.count=3;command.labor_count=3;command.release_allocation_ids={"farm.labor"};auto token=f.common.begin_savepoint();assert(token.ok);auto recruited=apply_organization_recruit_command(f.common,f.organizations,f.org_catalog,f.economy,f.activities,command,0);if(!recruited.ok){std::cerr<<recruited.error.original.code<<"\n";std::abort();}assert(f.common.commit_savepoint(token.value).ok);assert(f.economy.cohorts.find("workers")->headcount==7&&f.economy.cohorts.find("trainees")->headcount==3&&f.economy.labor_allocations.find("farm.labor")->workers==7&&f.common.wallet("family.wallet")->balance==wallet);const auto activity=f.organizations.activities.rows()[0].first;f.validate();
    f.step(1);auto advanced=step_organization_activities(f.common,f.organizations,f.org_catalog,f.economy,f.activities,f.results,{0,1,{activity},{},{}});assert(advanced.ok&&advanced.value.fact_ids.empty());f.step(2);advanced=step_organization_activities(f.common,f.organizations,f.org_catalog,f.economy,f.activities,f.results,{1,2,{activity},{},{}});assert(advanced.ok&&f.economy.cohorts.find("trainees")->status==PopulationStatus::trained_reserve&&!f.economy.cohorts.find("trainees")->assignment_id&&f.economy.labor_allocations.size()==1);auto count=f.common.count("city.inventory","grain",{{Owner::Kind::organization,"city",{}}});assert(count.ok&&count.value==14);const auto sequence=f.common.state().next_instance_id;advanced=step_organization_activities(f.common,f.organizations,f.org_catalog,f.economy,f.activities,f.results,{1,2,{activity},{},{}});assert(advanced.ok&&f.common.state().next_instance_id==sequence);f.validate();}
// 新活动不补领刚结束半日进度；严格冷枚举和全部目录字段能往返。
void codec_and_capture(){Fixture f;auto lc=dynamic_economy_codec::encode(f.catalog);assert(decode_local_economy_catalog(lc).ok);auto oc=dynamic_economy_codec::encode(f.org_catalog);assert(decode_organization_catalog(oc).ok);auto state=encode_local_economy_state(f.economy);state.find("cohorts")->find("workers")->find("status")->data=StableId("made_up");assert(!decode_local_economy_state(state).ok);auto broken=f.economy;broken.provision_bindings.insert("duplicate",{"duplicate",{SubjectKind::cohort,"workers"},0,100,"city.inventory","workers.food",ProvisionOwner::macro});OrganizationAccess access(f.common,f.organizations,f.org_catalog,f.economy);assert(!validate_local_economy(f.common,broken,f.catalog,access).ok);}
// 源库存观察冻结历史且包含预留实物；纯预览和未改变来源均不消耗 ID。
void observation_and_preview(){Fixture f;const auto first=f.economy.supply_observations.rows()[0].second;auto before=f.common.state().next_instance_id;auto repeat=refresh_local_supply_observations(f.common,f.economy,f.catalog,0);assert(repeat.ok&&f.common.state().next_instance_id==before);Owner city{Owner::Kind::organization,"city",{}};assert(f.common.apply_resources({{AddLot{"city.inventory","grain",5,city,{}}},{}}).ok);auto changed=refresh_local_supply_observations(f.common,f.economy,f.catalog,0);assert(changed.ok&&changed.value[0].physical_amount==25&&changed.value[0].source_fact_id!=first.id);auto old=local_economy_dynamic_fact(f.economy,first.id);assert(old&&old->supply&&old->supply->physical_amount==20&&!old->publicly_visible);assert(f.common.apply_resources({{ReserveLots{"city.inventory","grain",3,{city},"hold"}},{}}).ok);auto reserved=refresh_local_supply_observations(f.common,f.economy,f.catalog,0);assert(reserved.ok&&reserved.value[0].physical_amount==25);
    OrganizationRecruitCommand command;command.authority={"city","mayor.office",0,"mayor"};command.source_cohort_id="workers";command.target_cohort_id="trainees";command.activity_terms_id="voluntary.training";command.count=3;command.labor_count=3;command.release_allocation_ids={"farm.labor"};before=f.common.state().next_instance_id;auto state=encode_local_economy_state(f.economy);assert(preview_organization_recruit_command(f.common,f.organizations,f.org_catalog,f.economy,f.activities,command,0).ok);command.count=100;assert(!preview_organization_recruit_command(f.common,f.organizations,f.org_catalog,f.economy,f.activities,command,0).ok);assert(before==f.common.state().next_instance_id&&compare_boundary(state,encode_local_economy_state(f.economy)).exact());}
// 真实缺粮按有限整数规则减少产出，不制造人口死亡或补发资源。
void shortage_and_labor_intervals(){Fixture f;Owner city{Owner::Kind::organization,"city",{}};assert(f.common.apply_resources({{ConsumeLots{"city.inventory","grain",19,{city},{}}},{}}).ok);f.step(1);assert(f.economy.rations.rows()[0].second.required==10&&f.economy.rations.rows()[0].second.consumed==1&&f.economy.rations.rows()[0].second.shortage==9);const auto& production=f.economy.production_receipts.rows()[0].second;assert(production.allocated_workers==10&&production.effective_workers==1&&production.outputs[0].quantity==1);assert(f.economy.cohorts.find("workers")->headcount==10);f.validate();
    Fixture future;future.economy.labor_allocations.find("farm.labor")->through_tick=1;future.catalog.labor_allocations.find("farm.labor")->through_tick=1;assert(allocate_labor(future.common,future.economy,{"later","workers","farm",10,2,10,"farm"}).ok);OrganizationRecruitCommand command;command.authority={"city","mayor.office",0,"mayor"};command.source_cohort_id="workers";command.target_cohort_id="trainees";command.activity_terms_id="voluntary.training";command.count=3;command.labor_count=3;command.release_allocation_ids={"farm.labor"};assert(!preview_organization_recruit_command(future.common,future.organizations,future.org_catalog,future.economy,future.activities,command,0).ok);command.release_allocation_ids.push_back("later");auto token=future.common.begin_savepoint();assert(token.ok);auto recruited=apply_organization_recruit_command(future.common,future.organizations,future.org_catalog,future.economy,future.activities,command,0);assert(recruited.ok&&future.common.commit_savepoint(token.value).ok);assert(future.economy.labor_allocations.find("later")->workers==7);}
// 直接核对正式作者域与严格 native decoder，避免另一套初始化规则充当证明。
int decode_formal(const char* path){std::ifstream file(path);std::string text((std::istreambuf_iterator<char>(file)),{});auto root=parse_boundary_json(text);if(!root.ok)return 1;auto* scenarios=root.value.find("scenarios");if(!scenarios)return 1;for(const auto& scenario:boundary::array(*scenarios,"/scenarios")){const auto& dynamic=boundary::field(scenario,"dynamic_world","/scenario");auto economy=decode_local_economy_catalog(boundary::field(dynamic,"local_economy","/dynamic_world"));auto organization=decode_organization_catalog(boundary::field(dynamic,"organization","/dynamic_world"));if(!economy.ok||!organization.ok){const auto& error=economy.ok?organization.error:economy.error;std::cerr<<error.original.code<<" "<<error.original.path<<"\n";return 1;}std::cout<<boundary::get_string(scenario,"id","/scenario")<<": native economy/organization catalog decode PASS\n";}return 0;}
int main(int argc,char** argv){if(argc==2)return decode_formal(argv[1]);wage_and_checkpoint();rollback_and_overflow();authority_and_members();accepted_contract_services();terminal_action_outcomes();population_training();codec_and_capture();observation_and_preview();shortage_and_labor_intervals();std::cout<<"dynamic_economy: PASS (exact arrears/retry/checkpoint/atomic rollback/authority/member commitments/population/training/immutable supply/pure preview/food and labor bounds)\n";}
